# Transparency for Reviewer 2(4). The threshold below is newly specified for
# the R2 audit; historical "fails gate" annotations were not generated by an
# explicit gate in the archived scripts and must not be misrepresented.
script_dir <- dirname(normalizePath(sub("^--file=", "", grep("^--file=", commandArgs(FALSE), value=TRUE)[1L])))
source(file.path(script_dir,"reviewer_metrics.R"))
T <- as.numeric(Sys.getenv("STAGE1_THRESHOLD","0.60"))
if (!is.finite(T) || T <= 0 || T >= 1) stop("invalid Stage-1 threshold")
datadir <- file.path(script_dir,"..","data")
out <- list()
n1 <- file.path(datadir,"N1_results.rds")
if (file.exists(n1)) {
  obj <- readRDS(n1)
  for (noise in names(obj)) {
    z <- obj[[noise]]
    for (method in c("NPKDC-vd","SVM")) {
      v <- if (method == "NPKDC-vd") z$acc_npk else z$acc_svm
      out[[length(out)+1L]] <- data.frame(study="study2",setting=noise,method=method,
          B=length(v),mean_accuracy=mean(v),threshold=T,pass=stage1_gate(mean(v),T))
    }
  }
}
n6 <- file.path(datadir,"N6_results.rds")
if (file.exists(n6)) {
  z <- readRDS(n6)
  for (method in c("NPKDC-vd","OvR-RF")) {
    v <- if (method=="NPKDC-vd") z$np_acc_vec else z$rf_acc_vec
    v <- v[is.finite(v)]
    if (length(v)) out[[length(out)+1L]] <- data.frame(study="study5",setting="original N6",
     method=method,B=length(v),mean_accuracy=mean(v),threshold=T,pass=stage1_gate(mean(v),T))
  }
}
if (!length(out)) stop("Original accuracy RDS files were not found")
audit <- do.call(rbind,out)
write.csv(audit,file.path(reviewer_output_dir(),"stage1_accuracy_gate_audit.csv"),row.names=FALSE)
print(audit)
cat("Gate: mean held-out accuracy >= ",T,"; newly declared for R2, NOT previously coded.\n",sep="")
